programs.haiku:
"""Layer 15, MLP hidden unit 514 (the component reads almost only this unit).

What it does: it is near zero in ordinary prose, and rises on numbers and
single-letter variables written as mathematical notation, most of all right
after an opening bracket, as in the coordinates "(x, y)", "([4]", "(a, b)".
Plain numbers in running text, and numbers inside citations or dates, stay
near zero.

The program predicts a number from the current token and the one before it:
  - a digit or a single-letter variable directly after "(", "[", "{" or "_{"/"^{"
    gets the large value;
  - a digit or variable among other math symbols in the last few tokens gets a
    small value;
  - a plain digit gets a small value;
  - everything else gets 0.
"""

READS = ()

MATH_SYMBOLS = set("=+-*/^()[]{}<>|_\\×÷≤≥≈√∑∫")
OPEN_SUFFIXES = ("(", "[", "{", "_{", "^{")
AFTER_OPEN = 1.8
MATH_CONTEXT = 0.2
PLAIN_DIGIT = 0.25
PLAIN_VAR = 0.1
WINDOW = 8


def is_digit(s):
    return s.strip().isdigit()


def is_var(s):
    s = s.strip()
    return len(s) == 1 and s.isalpha()


def is_mathy(s):
    s = s.strip()
    return bool(s) and (is_digit(s) or is_var(s) or all(c in MATH_SYMBOLS for c in s))


def step(carry, prefix, upstream):
    t = prefix.position
    if t == 0:
        return carry, 0.0
    docs = prefix.document_ids
    strings = prefix.token_strings
    cur = strings[t]
    if not (is_digit(cur) or is_var(cur)):
        return carry, 0.0
    if docs[t - 1] != docs[t]:
        prev = ""
    else:
        prev = strings[t - 1]
    if prev.strip().endswith(OPEN_SUFFIXES):
        return carry, AFTER_OPEN
    mathy = 0
    for i in range(max(0, t - WINDOW), t):
        if docs[i] == docs[t] and is_mathy(strings[i]):
            mathy += 1
    if mathy >= 2:
        return carry, MATH_CONTEXT
    if is_digit(cur):
        return carry, PLAIN_DIGIT
    return carry, PLAIN_VAR

"""Layer 15 MLP down-projection, component 519.

What it responds to: the surface form of the current token, and for LaTeX
command names the token just before it. It is high on symbols and markup that
act as separators or decorations: dashes, ellipses, arrows, bullets, math and
currency signs, chat-template tags, and broken UTF-8 fragments. It is moderately
high on code and markup glyphs (underscore, backslash, pipe, tilde, at, hash,
dollar, star, ampersand, backtick), on square and curly brackets, on the name
of a LaTeX command (a word right after a backslash), on ALL-CAPS words, and on
whitespace tokens holding a no-break space or a carriage return. It is near
zero on letters, digits and ordinary sentence and code punctuation (commas,
periods, colons, parentheses, equals), and slightly negative on ordinary
lowercase words that start a new word.

The program predicts with one value per class of token, read off the token's
characters. It keeps no memory between positions.
"""

import re
import unicodedata

READS = ()

CHAT_TAGS = {
    "<|im_start|>", "<|im_end|>", "<think>", "</think>",
    "<tool_call>", "</tool_call>", "<tool_response>", "</tool_response>",
}
TYPOGRAPHIC = set("—–‐‑−•·°±×→⇒✓★§¶®©™€£¥～")
ELLIPSES = {"...", "....", "…"}
CODE_GLYPHS = set("_|\\~@#$%*^&`")
BRACKETS = set("[]{}")


def guess(s, prev):
    """Predicted activation for a token `s` whose left neighbour is `prev`."""
    if s in CHAT_TAGS:
        return 3.3
    if "�" in s:
        return 0.8
    core = s.strip()
    spaced = s[:1] in (" ", "\xa0")  # the token starts a new word
    if not core:
        return 1.9 if "\xa0" in s or "\r" in s or ("\n" in s and len(s) >= 8) else 0.0
    if re.fullmatch(r"[0-9]+", core):
        return 0.1
    if re.fullmatch(r"[A-Za-z]+", core):
        if not spaced and prev.rstrip().endswith("\\"):
            return 0.9
        if spaced and core.isupper() and len(core) > 1:
            return 0.5
        return -0.08 if spaced else 0.0
    if core in ELLIPSES:
        return 3.0
    if set(core) <= TYPOGRAPHIC or core in ("--", "---"):
        return 2.7
    if core == "-":
        return 0.6
    if set(core) <= CODE_GLYPHS:
        return 1.4
    if set(core) <= BRACKETS:
        return 0.8
    if all(ord(c) > 127 and unicodedata.category(c)[0] == "S" for c in core):
        return 2.9
    return 0.0


def step(carry, prefix, upstream):
    same_doc = len(prefix.token_strings) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = prefix.token_strings[-2] if same_doc else ""
    return carry, guess(prefix.token_strings[-1], prev)

"""Layer 15 MLP down_proj, component 530: a small, mostly-quiet feature.

Most tokens get an activation near zero, with occasional large values. The
readable patterns in the text it responds to:

* positive on "of" in fixed title or relation phrases: "country of citizenship",
  "statute of limitations", "House of Representatives", "place of birth",
  "species of", "Court of". The word "birth" after "place of" is positive too.
* negative on "of" after a quantity word: "one of", "each of", "number of".
* mildly negative on a possessive 's.
* negative on relational hyphen-suffix words that close a technical compound:
  "-induced", "-dependent", "-specific", "-related", "-mediated".
* weakly positive on a hyphen joining a word to the next piece.

Everything else predicts 0. These patterns explain only a small part of the
variance. Most of the activation is a diffuse, context-dependent spread on
content words in technical text, which no word list captures.
"""

from collections.abc import Mapping

READS: tuple[str, ...] = ()

TITLE_HEADS = {
    "country", "statute", "House", "place", "species", "language", "Court",
    "court", "Board", "Member", "Code", "rule", "rules", "States", "Register",
    "Field", "territorial",
}
QUANTITY_HEADS = {
    "one", "each", "all", "any", "some", "number", "set", "part", "amount",
    "most", "lot", "piece", "sum", "none", "both", "many", "group",
}
RELATIONAL_SUFFIXES = {
    "-induced", "-dependent", "-specific", "-related", "-mediated",
    "-derived", "-binding", "-supported",
}
POSSESSIVES = {"'s", "’s"}
HYPHENS = {"-", "‐", "‑"}


def step(carry, prefix, upstream: Mapping):
    tokens = prefix.token_strings
    docs = prefix.document_ids
    cur = tokens[-1]
    same_doc = len(tokens) > 1 and docs[-2] == docs[-1]
    prev = tokens[-2].strip() if same_doc else ""
    value = 0.0
    if cur == " of" and prev in TITLE_HEADS:
        value = 3.0
    elif cur == " of" and prev in QUANTITY_HEADS:
        value = -1.0
    elif cur == " birth" and prev == " of":
        value = 1.5
    elif cur in POSSESSIVES:
        value = -0.4
    elif cur in RELATIONAL_SUFFIXES:
        value = -2.0
    elif cur in HYPHENS and prev.isalpha():
        value = 0.25
    return carry, float(value)

"""Layer 15 MLP down_proj component 532: a weak, mostly token-level newline/whitespace detector.

Measured on 2M training tokens, this component's activation is almost unpredictable from
the current token: its large values are tied to newlines and indentation whitespace (where
its causal importance is high), but most of its variance is context noise. This program
predicts a small class-mean value for each kind of token:

- a line break that ends a blank, tab-indented line: large positive (rare, strong);
- a line break right after an opening bracket, brace or colon: moderately positive;
- any other line break, except one after a closing bracket or semicolon: small positive;
- a line break after a closing bracket or semicolon: slightly negative;
- whitespace-only tokens (indentation): about zero;
- every other token: slightly negative, the component's usual resting level.
"""

from collections.abc import Mapping

READS: tuple[str, ...] = ()

OPENERS = "{([:"
CLOSERS = "};)"


def step(carry, prefix, upstream: Mapping):
    tok = prefix.token_strings[-1]
    if "\n" in tok or "\r" in tok:
        body = tok.replace("\r", "").replace("\n", "")
        if "\t" in body and body.strip() == "":
            return carry, 2.9
        last = body.rstrip()[-1:]
        if last and last in OPENERS:
            return carry, 0.42
        if last and last in CLOSERS:
            return carry, -0.06
        return carry, 0.14
    if tok != "" and tok.strip() == "":
        return carry, -0.04
    return carry, -0.08

"""Predicts the mean activation on the word "that" (mostly the complementizer in "knew
that ..."), 0 elsewhere. The component's activation has no other simple word-level trend."""

READS = ()


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    return carry, (0.27 if word == "that" else 0.0)

"""Weak, diffuse predictor for layers.15.mlp.down_proj:538.

The component's activation is a small, noisy number (mean about +0.05, std 0.33) with no
clean trigger; its contribution to the output is negligible. What it does show is:
  - the first token of a row is about 0, and the second token is clearly low (about -0.14),
    the third and fourth a little low;
  - it leans positive on words of obligation, need and correctness (should, must, need,
    necessary, important, correct, proper, useful, good, will, can, could, would);
  - it leans negative on month names, government-office titles and code/markup tags.
Everything else sits near the average, about +0.05.
"""

READS = ()

NECESSITY = {
    "should", "must", "need", "needs", "ought", "required", "necessary", "essential",
    "important", "proper", "correct", "appropriate", "useful", "helpful", "good",
    "will", "can", "could", "would",
}
MONTHS = {
    "January", "February", "March", "April", "May", "June", "July", "August",
    "September", "October", "November", "December",
}
OFFICES = {
    "President", "Secretary", "Minister", "Congress", "Senate", "government",
    "Court", "speaker", "Institute", "United",
}
MARKUP = {"<tool_call>", "</tool_call>", "<tool_response>", "</tool_response>", "/workspace", "usr"}

BASE = 0.05
UP = 0.25
DOWN = -0.15


def step(carry, prefix, upstream):
    pos = prefix.position
    if pos == 0:
        return carry, 0.0
    if pos == 1:
        return carry, -0.14
    if pos < 4:
        return carry, -0.05
    word = prefix.token_strings[-1].strip()
    if word.lower() in NECESSITY:
        return carry, UP
    if word in MONTHS or word in OFFICES or word in MARKUP:
        return carry, DOWN
    return carry, BASE

"""Layer 15 MLP down-projection, component 546.

What it does: a "predicate verb" feature. It is strongly positive on the finite
verb that says what a noun subject is or does, the word right after the subject:
"X IS a ...", "Y WAS published", "Z PROVIDES ...", "W CONSISTS of ...", "... CAN be
...". It is weaker after a pronoun subject ("it is", "that can", "they are"), mildly
positive on modals, "has", and on adverbs such as "not", "often", "typically" that
sit between subject and verb, and on a/an right after "is" ("is a ..."). Capitalised
auxiliaries (questions: "Is it", "Be careful") do not fire, and subject pronouns
are slightly negative. Everything else is about zero.

The values are hand-set typical activations read off the data, not fitted weights.
"""
import wordnet

READS = ()

COPULA = {"is", "are", "was", "were", "be", "been"}
MODAL = {"can", "may", "will", "must", "should", "could", "would", "shall", "might"}
HAVE = {"has", "have", "had"}
ADVERBS = {"not", "often", "typically", "usually", "also", "only", "generally", "commonly"}
PRONOUN_SUBJECTS = {"it", "they", "that", "which", "i", "this", "there", "what", "we",
                    "you", "he", "she", "who", "one"}
SUBJECT_PRONOUNS = {"it", "they", "that", "which", "this", "i", "what", "who"}
_verb_cache = {}


def is_verb_form(w, ending):
    """A verb ending in `ending` (-s: provides, includes; -ed: located), not also a noun."""
    key = (w, ending)
    if key not in _verb_cache:
        pos = wordnet.parts_of_speech(w)
        _verb_cache[key] = (len(w) > 3 and w.endswith(ending) and "verb" in pos
                            and "noun" not in pos)
    return _verb_cache[key]


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    if not tok.startswith(" "):
        return carry, 0.0
    w = tok.strip().lower()
    same_doc = len(prefix.document_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = prefix.token_strings[-2].strip().lower() if same_doc else ""
    after_pronoun = prev in PRONOUN_SUBJECTS
    capitalised = tok[1:2].isupper()
    if w in COPULA or w in MODAL or w in HAVE:
        if capitalised:
            value = 0.0
        elif w in COPULA:
            value = 1.6 if after_pronoun else 2.9
        elif w in MODAL:
            value = 0.5 if after_pronoun else 1.5
        else:
            value = 0.9
    elif w in ADVERBS:
        value = 1.1
    elif is_verb_form(w, "s") and not w.endswith("ss"):
        value = 1.8 if after_pronoun else 2.85
    elif is_verb_form(w, "ed"):
        value = 0.5
    elif w in SUBJECT_PRONOUNS:
        value = -0.35
    elif w in ("a", "an") and prev in COPULA:
        value = 2.4
    else:
        value = 0.0
    return carry, value

"""Layer 15 MLP hidden unit 560 (down_proj component 560), a weak, diffuse neuron.

What it does: its value is high-ish on words that introduce a measured quantity or
its scale ("approximately", "average", "annual", "per", "roughly", currency and
time-zone codes, units such as mg, kg, ml), and on a closing parenthesis, which
often ends such a phrase. It is negative on patent and code boilerplate
("invention", "embodiment", "preferred", "claims", ".git", "/python", code fences).
Everywhere else it predicts 0.

The weights are the class means fitted on training text; they are small, so this
program explains only a little of the variance (see the explanation).
"""

QUANTITY = {
    "approximately", "roughly", "about", "around", "average", "averages", "mean",
    "median", "annual", "annually", "per", "estimated", "estimate", "percentage",
    "proportion", "typical", "daily", "monthly", "yearly", "year", "years",
    "utc", "gmt", "eur", "usd", "gbp", "rs",
}
UNITS = {
    "mg", "kg", "g", "ml", "cm", "mm", "m", "psi", "ph", "mol", "ppm",
    "/ml", "/kg", "µg", "μg",
}
BOILERPLATE = {
    "invention", "embodiment", "embodiments", "preferred", "preferably", "claims",
    "claim", ".git", "/python", "```", "</tool_call>", "cat", "eof",
}

READS = ()


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if word in QUANTITY:
        value = 0.2
    elif word in UNITS:
        value = 0.05
    elif word == ")":
        value = 0.15
    elif word in BOILERPLATE:
        value = -0.43
    else:
        value = 0.0
    return carry, value

"""Predict the component's mean activation, with a small adjustment by kind of token.

Component p-82af68dd@100000/layers.15.mlp.down_proj:561 has activation mean ~0.01 and
std ~0.32, and it is essentially unpredictable from the text: the current token, the
previous token, position, nearby token mix, repetition and document-level statistics
each explain ~0 of its variance out of sample. This program only encodes the small
average differences between kinds of token that were measured:

- the first token of a document: 0 (the component is silent there);
- a line break: slightly above the mean;
- other whitespace: a little above the mean;
- everything else: about the mean.

On the eval rows it explains about 0.2% of the activation variance (Pearson r 0.04),
and it leaves the model's next-token predictions essentially unchanged.
"""

READS = ()


def step(carry, prefix, upstream):
    if prefix.position == 0:
        return carry, 0.0
    text = prefix.token_strings[-1]
    if "\n" in text:
        return carry, 0.08
    if text.strip() == "":
        return carry, 0.03
    return carry, 0.01

"""Layer 15 MLP down_proj, component 572.

What it does, in plain terms: it fires on words that open an embedded phrase or a
quotation in running English prose. Strongest is the passive agent "by" ("was
captured by", "is designed by"); next come an opening parenthesis, bracket or quote
mark ("Name (born ...)", 'the "Grey Ghosts"'). It is weaker on contrast connectives
("but", "However", "Therefore", "So"), on dashes and on semicolons or bars. The same
tokens inside code (`if (`, `{`, `==`, `;`) give little or nothing, so each
strength is scaled by "prose-ness": the share of the last 20 tokens of the document
that are alphabetic words. Ordinary tokens (spaces, commas, digits, "the") are
predicted as 0. Their real values scatter around 0 (std about 0.8) with no simple
pattern found, and that scatter is most of the variance this program leaves unexplained.

Program: for each position, read the current token and the prose share of the
window. Openers and "by" rise from about 1.3 (code-like context) to 4 (prose); dashes
rise linearly with prose; connectives and separators take fixed values.
"""

from collections.abc import Mapping

READS: tuple[str, ...] = ()

AGENT_BY = {" by", " By"}
OPENERS = {" (", "(", " [", "[", " \"", " “", " ‘", " '", " `", "「", "（", " «", " „"}
CONNECTIVES = {" but", " But", " so", " So", " however", " However", " Therefore", " therefore", " Thus", " thus"}
DASHES = {" —", " –", " -", "—", "–", " --", "--"}
SEPARATORS = {";", "；", " |", " #", " //", "__"}

WINDOW = 20


def is_word(text):
    text = text.strip()
    return len(text) >= 2 and text.isalpha()


def prose_share(prefix):
    """Share of the last WINDOW tokens of this document that are alphabetic words."""
    t = prefix.position
    doc = prefix.document_ids[t]
    span = [i for i in range(max(0, t - WINDOW + 1), t + 1) if prefix.document_ids[i] == doc]
    return sum(is_word(prefix.token_strings[i]) for i in span) / len(span)


def ramp(prose, low, high, start=0.3, stop=0.6):
    """Linear rise from `low` at prose share `start` to `high` at `stop`."""
    frac = min(max((prose - start) / (stop - start), 0.0), 1.0)
    return low + (high - low) * frac


def step(carry, prefix, upstream: Mapping):
    token = prefix.token_strings[prefix.position]
    prose = prose_share(prefix)
    if token in AGENT_BY or token in OPENERS:
        value = ramp(prose, 1.3, 4.0)
    elif token in DASHES:
        value = 2.6 * prose
    elif token in CONNECTIVES:
        value = 2.0
    elif token in SEPARATORS:
        value = 1.5
    else:
        value = 0.0
    return carry, float(value)
